#[test]
fn parses_like_the_reference() {
    for (input, expected) in PARSING {
        let actual = ShorthandParser::parse(input).unwrap_or_else(|e| panic!("{input:?}: {e:?}"));
        assert_eq!(actual, pyjson::loads(expected).unwrap(), "{input:?}");
    }
}

#[test]
fn errors_like_the_reference() {
    for (input, expected) in ERRORS {
        match ShorthandParser::parse(input) {
            Err(ShorthandError::Parse(m)) => assert_eq!(m, *expected, "{input:?}"),
            other => panic!("{input:?}: {other:?}"),
        }
    }
}
